import { Object3D, Mesh, PlaneGeometry, Color, Vector2 } from "three/webgpu";
import {
  MeshStandardNodeMaterial,
  color,
  uv,
  mix,
  float,
  add,
  subtract,
  mul,
  step,
  length,
  vec3,
} from "three/tsl";
import { gsap } from "gsap";
import { primitives as _primitives } from "@/primitives";
import { createTextMesh } from "@/text";

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Object} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} primitives
 * @property {any} fontAtlas
 */

/**
 * Creates the footer colophon node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  // -------------------------------------------------------------------------
  // Constants from design tokens
  // -------------------------------------------------------------------------
  const COLORS = {
    background: new Color("#0b0b10"),
    surface: new Color("#101015"),
    ink: new Color("#16161d"),
    paper: new Color("#e8ecf2"),
    accent: new Color("#ff2a38"),
    hairline: new Color("#23232b"),
    gradientTop: new Color("#121218"),
    gradientBottom: new Color("#0b0b10"),
  };

  const FOOTER = {
    width: 6.8,
    height: 2.0,
    hairlineHeight: 0.006,
    accentBar: { width: 0.3, height: 0.02, emissiveIntensity: 1.4 },
    baseY: 0, // centre of the plane
  };

  // -------------------------------------------------------------------------
  // Root container
  // -------------------------------------------------------------------------
  const root = new Object3D();
  root.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  root.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  root.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // -------------------------------------------------------------------------
  // Base plane with vertical gradient (albedo) and PBR properties
  // -------------------------------------------------------------------------
  const baseGeometry = new PlaneGeometry(FOOTER.width, FOOTER.height);
  const gradientNode = mix(
    color(COLORS.gradientTop),
    color(COLORS.gradientBottom),
    uv().y
  );

  const baseMaterial = new MeshStandardNodeMaterial({
    color: gradientNode,
    metalness: float(0.2),
    roughness: float(0.6),
    transparent: true,
    opacity: float(1),
  });
  baseMaterial.side = 2; // DoubleSide

  const baseMesh = new Mesh(baseGeometry, baseMaterial);
  root.add(baseMesh);

  // -------------------------------------------------------------------------
  // Top hairline rule (etched look – relies on specular edge)
  // -------------------------------------------------------------------------
  const hairlineGeometry = new PlaneGeometry(
    FOOTER.width,
    FOOTER.hairlineHeight
  );
  const hairlineMaterial = new MeshStandardNodeMaterial({
    color: color(COLORS.hairline),
    metalness: float(0.1),
    roughness: float(0.4),
    transparent: true,
    opacity: float(1),
  });
  const hairlineMesh = new Mesh(hairlineGeometry, hairlineMaterial);
  hairlineMesh.position.y = FOOTER.height / 2 - FOOTER.hairlineHeight / 2; // top edge
  root.add(hairlineMesh);

  // -------------------------------------------------------------------------
  // Accent bar beneath the wordmark
  // -------------------------------------------------------------------------
  const accentGeometry = new PlaneGeometry(
    FOOTER.accentBar.width,
    FOOTER.accentBar.height
  );
  const accentMaterial = new MeshStandardNodeMaterial({
    color: color(COLORS.surface),
    emissive: color(COLORS.accent),
    emissiveIntensity: float(FOOTER.accentBar.emissiveIntensity),
    metalness: float(0.0),
    roughness: float(0.5),
    transparent: true,
    opacity: float(1),
  });
  const accentMesh = new Mesh(accentGeometry, accentMaterial);
  // Position: left block occupies 2.0 units, centred at - (width/2) + 1.0
  const leftBlockCenterX = -FOOTER.width / 2 + 1.0;
  accentMesh.position.set(
    leftBlockCenterX,
    FOOTER.height / 2 - 0.4, // slightly below the top edge of the band
    0.01
  );
  root.add(accentMesh);

  // -------------------------------------------------------------------------
  // Text creation helper
  // -------------------------------------------------------------------------
  const textMeshes = [];

  /**
   * Adds a text mesh to the scene.
   * @param {string} txt
   * @param {Object} style - {family, fontSize, fontWeight, letterSpacing, lineHeight, color}
   * @param {Vector2} pos - position in scene units (x, y)
   */
  function addText(txt, style, pos) {
    const mesh = createTextMesh(ctx.fontAtlas, txt, {
      family: style.family,
      size: style.fontSize * 0.01, // convert px to scene‑unit scale (approx)
      weight: style.fontWeight,
      letterSpacing: style.letterSpacing,
      lineHeight: style.lineHeight,
      color: style.color,
    });
    mesh.position.set(pos.x, pos.y, 0.02);
    root.add(mesh);
    textMeshes.push(mesh);
  }

  // -------------------------------------------------------------------------
  // Layout calculations (baseline grid = 0.25)
  // -------------------------------------------------------------------------
  const baseline = 0.25;
  const columnWidth = 1.2;
  const gutter = 0.375;
  const startX = -FOOTER.width / 2 + 2.0 + gutter / 2; // after left block + first gutter

  const columnX = [
    startX,
    startX + columnWidth + gutter,
    startX + 2 * (columnWidth + gutter),
  ];

  const topY = FOOTER.height / 2 - baseline; // just under top hairline

  // Wordmark
  addText("NOVA ATELIER", {
    family: "Lora",
    fontSize: 34,
    fontWeight: 600,
    letterSpacing: 0.02,
    lineHeight: 1,
    color: COLORS.ink,
  }, new Vector2(-FOOTER.width / 2 + 1.0, topY - baseline));

  // Columns
  const columns = [
    {
      header: "ATELIER",
      links: ["Features", "Collection", "Pricing"],
    },
    {
      header: "COMPANY",
      links: ["Journal", "Visit the Atelier", "Contact"],
    },
    {
      header: "LEGAL",
      links: ["Privacy", "Terms", "Warranty"],
    },
  ];

  columns.forEach((col, idx) => {
    const x = columnX[idx] - FOOTER.width / 2 + columnWidth / 2;
    let y = topY - baseline * 2; // start a bit lower than wordmark

    // Header
    addText(col.header, {
      family: "JetBrains Mono",
      fontSize: 9,
      fontWeight: 700,
      letterSpacing: 0.12,
      lineHeight: 1.2,
      color: COLORS.ink,
    }, new Vector2(x, y));
    y -= baseline * 1.2; // move down for first link

    // Links
    col.links.forEach((lnk) => {
      addText(lnk, {
        family: "JetBrains Mono",
        fontSize: 13,
        fontWeight: 400,
        letterSpacing: 0,
        lineHeight: 1.8,
        color: COLORS.ink,
      }, new Vector2(x, y));
      y -= baseline * 1.8;
    });
  });

  // Legal line (full width, near bottom)
  const legalY =
    -FOOTER.height / 2 + baseline * 2; // 0.375 above bottom hairline
  addText(
    "(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.",
    {
      family: "JetBrains Mono",
      fontSize: 9,
      fontWeight: 400,
      letterSpacing: 0.04,
      lineHeight: 1.4,
      color: COLORS.ink,
    },
    new Vector2(0, legalY)
  );

  // -------------------------------------------------------------------------
  // Bottom hairline rule (separating legal line)
  // -------------------------------------------------------------------------
  const bottomHairline = new Mesh(
    new PlaneGeometry(FOOTER.width, FOOTER.hairlineHeight),
    new MeshStandardNodeMaterial({
      color: color(COLORS.hairline),
      metalness: float(0.1),
      roughness: float(0.4),
      transparent: true,
      opacity: float(1),
    })
  );
  bottomHairline.position.y =
    -FOOTER.height / 2 + FOOTER.hairlineHeight / 2 + baseline * 0.25;
  root.add(bottomHairline);

  // -------------------------------------------------------------------------
  // Apply cinematic primitives if any (none in spec, but keep loop for safety)
  // -------------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives?.[primitive.name];
      if (typeof fn === "function") {
        fn(root, primitive.params);
      }
    });
  }

  // -------------------------------------------------------------------------
  // Animation (fade‑up of whole band)
  // -------------------------------------------------------------------------
  // start offset
  root.position.y += 0.2;
  // ensure materials are transparent for opacity tween
  root.traverse
